      sfx('thud', { volume: vol, pitch: 0.5, at: { x: x, y: y, z: z }, near: 40, far: 420, force: true });
      sfx('pop',  { volume: vol * 0.7, pitch: 0.7, at: { x: x, y: y, z: z }, near: 40, far: 420, force: true });
