  const sysCamOk = new THREE.Vector3(0, sysCAM_DEF, sysCAM_DEF);
  let shotReq = null, shotAge = 0, shotW = 0, shotKill = 0;
  let camDolly = 0;             // 0..1 of the run speed, damped. See sysCAM_DOLLY_P.
